// Serve the pinned npm D3 build locally, including its copyright header.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
export function GET() {
  return new Response(readFileSync(resolve('node_modules/d3/dist/d3.min.js')), {
    headers: { 'Content-Type': 'text/javascript; charset=utf-8' },
  });
}
